import re

_DECIMAL = {
    'b': 1,
    'kb': 10**3,
    'mb': 10**6,
    'gb': 10**9,
    'tb': 10**12,
    'pb': 10**15,
}

_BINARY = {
    'b': 1,
    'kib': 1024,
    'mib': 1024**2,
    'gib': 1024**3,
    'tib': 1024**4,
    'pib': 1024**5,
}


def parse_size(size_str: str) -> int:
    if not isinstance(size_str, str):
        raise ValueError('size_str must be a string')

    s = size_str.strip()
    if not s:
        raise ValueError('empty size string')

    # Match an optional sign, a number (int or float), optional whitespace, and an optional unit
    m = re.match(r'^([+-]?\d+(?:\.\d+)?)\s*([A-Za-z]*)$', s)
    if not m:
        raise ValueError(f'invalid size string: {size_str!r}')

    num_str, unit_str = m.group(1), m.group(2)

    try:
        value = float(num_str)
    except ValueError:
        raise ValueError(f'invalid number: {num_str!r}')

    unit = unit_str.lower()
    if unit == '':
        multiplier = 1
    elif unit in _DECIMAL:
        multiplier = _DECIMAL[unit]
    elif unit in _BINARY:
        multiplier = _BINARY[unit]
    else:
        raise ValueError(f'unknown unit: {unit_str!r}')

    return int(value * multiplier)
